106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
109	        HttpHeaders headers = new HttpHeaders();
110	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
111	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
112	        owner.setTelephone(normalizedTelephone);
113	        owner.setEmail(normalizeEmail(owner.getEmail()));
114	        if (owner.getRegistrationDate() == null) {
115	            owner.setRegistrationDate(LocalDate.now());
116	        }
117	        if (isTelephoneInUse(normalizedTelephone, null)) {
118	            throw new ResponseStatusException(HttpStatus.CONFLICT,
119	                "telephone is already in use by another owner");
120	        }
121	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
122	        if (!sharesHousehold
123	            && isHouseholdInUse(owner.getLastName(), owner.getAddress(), null)) {
124	            throw new ResponseStatusException(HttpStatus.CONFLICT,
125	                "another owner with the same last name already lives at this address");
126	        }
127	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
128	        if (sharesHousehold) {
129	            assignHousehold(owner);
130	        }
131	        this.clinicService.saveOwner(owner);
132	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
133	        headers.setLocation(UriComponentsBuilder.newInstance()
