232	    /**
233	     * Builds the customer code for a new owner, formatted {@code '<LAST3>-<NNNN>'} where LAST3 is the
234	     * upper-cased first three letters of the last name and NNNN is a global 4-digit zero-padded
235	     * sequence equal to one more than the current number of owners (e.g. {@code 'SMI-0007'}).
236	     *
237	     * @param lastName the owner's last name
238	     * @return the assigned customer code
239	     */
240	    private String nextCustomerCode(String lastName) {
241	        String prefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
242	        int sequence = this.clinicService.findAllOwners().size() + 1;
243	        return String.format("%s-%04d", prefix, sequence);
244	    }
245	
246	    /**
247	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. When
248	     * the value carries a leading {@code '+'} the following country code and digits are kept as-is;
249	     * otherwise country code {@code +61} is assumed and a single leading {@code '0'} is dropped from
250	     * the national digits. The result must be a {@code '+'} followed by 8 to 15 digits. This E.164
251	     * string is what gets stored and returned.
252	     *
253	     * <p>For example {@code "0412 345 678"} is normalized to {@code "+61412345678"}.
254	     *
255	     * @param telephone the raw telephone value supplied by the client
256	     * @return the normalized E.164 telephone number
257	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if the value cannot form a
258	     *                                 valid E.164 number (unexpected characters, or not 8 to 15
259	     *                                 digits after the {@code '+'})
260	     */
261	    private static String normalizeTelephone(String telephone) {
262	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
263	        String digits;
264	        if (cleaned.startsWith("+")) {
265	            digits = cleaned.substring(1);
266	        } else {
267	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
268	            digits = "61" + national;
269	        }
270	        if (!digits.matches("[0-9]{8,15}")) {
271	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
272	                "telephone could not be normalized to a valid E.164 number");
273	        }
274	        return "+" + digits;
275	    }
276	
277	    /**
278	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, falling back
279	     * to the raw stored value if it cannot be normalized (e.g. legacy seed data in another format).
280	     *
281	     * @param telephone the stored telephone value, possibly {@code null}
282	     * @return the E.164 form, or the raw value when it cannot be normalized
283	     */
284	    private static String toComparableTelephone(String telephone) {
285	        try {
286	            return normalizeTelephone(telephone);
287	        } catch (ResponseStatusException ex) {
288	            return telephone;
289	        }
290	    }
291	
292	    /**
293	     * Basic syntactic email validation: a non-empty local part, an {@code @}, and a domain
294	     * containing at least one dot, none of the three sections containing whitespace or an
295	     * additional {@code @}.
296	     */
297	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
298	
299	    /**
300	     * Validates and normalizes an optional owner email address. A {@code null} value is left as is
301	     * (email is optional). When a value is supplied it must be a syntactically valid address; the
302	     * value is then stored and returned lower-cased.
303	     *
304	     * @param email the raw email value supplied by the client, possibly {@code null}
305	     * @return the lower-cased email, or {@code null} when none was supplied
306	     * @throws ResponseStatusException with {@link HttpStatus#BAD_REQUEST} if a value is present but
307	     *                                 is not a syntactically valid address
308	     */
309	    private static String normalizeEmail(String email) {
310	        if (email == null) {
311	            return null;
312	        }
313	        if (!EMAIL_PATTERN.matcher(email).matches()) {
314	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
315	                "email must be a syntactically valid address");
316	        }
317	        return email.toLowerCase(Locale.ROOT);
318	    }
319	
320	    /**
321	     * Determines whether the given normalized E.164 telephone is already used by any owner other
322	     * than the one identified by {@code excludeId} (pass {@code null} to consider every owner, e.g.
323	     * on create). Stored telephones are compared by their E.164 value so that differently formatted
324	     * inputs representing the same number are treated as duplicates.
325	     *
326	     * @param normalizedTelephone the already-normalized E.164 telephone to look for
327	     * @param excludeId           id of an owner to ignore during the check, or {@code null} for none
328	     * @return {@code true} if another owner already uses the telephone
329	     */
330	    private boolean isTelephoneInUse(String normalizedTelephone, Integer excludeId) {
331	        for (Owner existing : this.clinicService.findAllOwners()) {
332	            if (excludeId != null && excludeId.equals(existing.getId())) {
333	                continue;
334	            }
335	            if (normalizedTelephone.equals(toComparableTelephone(existing.getTelephone()))) {
336	                return true;
337	            }
338	        }
339	        return false;
340	    }
341	
342	    /**
343	     * Normalizes a value for household comparison: leading/trailing whitespace is trimmed, internal
344	     * runs of whitespace are collapsed to a single space, and the result is lower-cased. This lets
345	     * two last names or addresses that differ only in case or whitespace be treated as equal.
346	     *
347	     * @param value the raw value, possibly {@code null}
348	     * @return the normalized comparison key, or {@code ""} when the value is {@code null}
349	     */
350	    private static String normalizeForHousehold(String value) {
351	        if (value == null) {
352	            return "";
353	        }
354	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
355	    }
356	
357	    /**
358	     * Determines whether another owner (other than {@code excludeId}, or every owner when it is
359	     * {@code null}) already shares the same household, i.e. has the same last name and the same
360	     * address compared case-insensitively with collapsed whitespace.
361	     *
362	     * @param lastName  the last name to check
363	     * @param address   the address to check
364	     * @param excludeId id of an owner to ignore during the check, or {@code null} for none
365	     * @return {@code true} if another owner shares the same last name and address
366	     */
367	    private boolean isHouseholdInUse(String lastName, String address, Integer excludeId) {
368	        String normalizedLastName = normalizeForHousehold(lastName);
369	        String normalizedAddress = normalizeForHousehold(address);
370	        for (Owner existing : this.clinicService.findAllOwners()) {
371	            if (excludeId != null && excludeId.equals(existing.getId())) {
372	                continue;
373	            }
374	            if (normalizedLastName.equals(normalizeForHousehold(existing.getLastName()))
375	                && normalizedAddress.equals(normalizeForHousehold(existing.getAddress()))) {
376	                return true;
377	            }
378	        }
379	        return false;
380	    }
381	
382	    /**
383	     * Derives the stable household identifier shared by all owners with the same last name and
384	     * address. The value is deterministic (the first 12 upper-case hex characters of the SHA-256
385	     * digest of the normalized last name and address), so every owner in the same household is
386	     * assigned an identical, non-blank identifier regardless of creation order.
387	     *
388	     * @param lastName the owner's last name
389	     * @param address  the owner's address
390	     * @return the stable household identifier
391	     */
392	    private static String householdIdFor(String lastName, String address) {
393	        String key = normalizeForHousehold(lastName) + "\n" + normalizeForHousehold(address);
394	        try {
395	            byte[] digest = MessageDigest.getInstance("SHA-256")
396	                .digest(key.getBytes(StandardCharsets.UTF_8));
397	            StringBuilder sb = new StringBuilder(digest.length * 2);
398	            for (byte b : digest) {
399	                sb.append(String.format("%02X", b));
400	            }
401	            return sb.substring(0, 12);
402	        } catch (NoSuchAlgorithmException ex) {
403	            throw new IllegalStateException("SHA-256 not available", ex);
404	        }
405	    }
406	
407	    /**
408	     * Assigns the shared household identifier to the given owner and to every existing owner that
409	     * already shares its household (same last name and address), so all members carry the same
410	     * stable value. Existing members whose identifier is missing or stale are updated and saved.
411	     *
412	     * @param owner the owner being created into (or as the seed of) a shared household
413	     */
414	    private void assignHousehold(Owner owner) {
415	        String householdId = householdIdFor(owner.getLastName(), owner.getAddress());
416	        owner.setHouseholdId(householdId);
417	        String normalizedLastName = normalizeForHousehold(owner.getLastName());
418	        String normalizedAddress = normalizeForHousehold(owner.getAddress());
419	        for (Owner existing : this.clinicService.findAllOwners()) {
420	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
421	                continue;
422	            }
423	            if (normalizedLastName.equals(normalizeForHousehold(existing.getLastName()))
424	                && normalizedAddress.equals(normalizeForHousehold(existing.getAddress()))
425	                && !householdId.equals(existing.getHouseholdId())) {
426	                existing.setHouseholdId(householdId);
427	                this.clinicService.saveOwner(existing);
428	            }
429	        }
430	    }
431	}
